INSERT OR IGNORE INTO trips (id, core_json, revision, write_token, created_at, updated_at)
SELECT 'trip_demo0000000000000000000000000000', json_remove(payload, '$.participants', '$.availabilityRanges', '$.availability', '$.transportOptions', '$.accommodationOptions', '$.activities'), 1, 'demo-seed-v1', '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z'
FROM demo_seed_migration;

INSERT OR IGNORE INTO participants (trip_id, id, payload, position, revision, write_token, created_at, updated_at)
SELECT 'trip_demo0000000000000000000000000000', json_extract(item.value, '$.id'), item.value, CAST(item.key AS INTEGER), 1, 'demo-seed-v1', '2026-10-04T00:00:00.000Z', '2026-10-04T00:00:00.000Z'
FROM demo_seed_migration, json_each(demo_seed_migration.payload, '$.participants') AS item;

